const $=id=>document.getElementById(id), money=n=>n.toLocaleString('fr-BE',{style:'currency',currency:'EUR'});
const {Game,ingredients,recipes}=BarEngine;
let saved=null;try{saved=JSON.parse(localStorage.getItem('comptoir-bar-v2'))}catch{}
const game=new Game(saved);let state=game.s,client=null,paused=false,last=performance.now(),elapsed=0,toastTimer,saveFailed=false;
function save(){try{localStorage.setItem('comptoir-bar-v2',JSON.stringify(game.s));saveFailed=false}catch{if(!saveFailed){toast('Sauvegarde indisponible : vérifiez l’espace disque.');saveFailed=true}}}
function toast(message){if(!message)return;$('toast').textContent=message;$('toast').style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.opacity=0,4000)}
function modal(title,html){game.setPour(false);keys={};document.exitPointerLock?.();$('modalTitle').textContent=title;$('modalContent').innerHTML=html;$('modal').showModal()}
function act(fn){if(paused){toast('Reprenez la partie pour continuer.');return}const result=fn();toast(result);audio.chime(typeof result==='string'&&result.startsWith('Servi !')?'sale':'click');state=game.s;save();ui()}
function ui(){state=game.s;$('cash').textContent=money(state.cash);$('day').textContent='SOIR '+state.day;const t=Math.min(1440,state.time);$('clock').textContent=t>=1440?'00:00':String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0');$('pause').textContent=paused?'Reprendre':'Pause';$('mission').textContent=state.gameOver?'Trésorerie épuisée. Commencez un nouveau bar.':state.totalSold<5?`Servez 5 clients pour agrandir le plateau (${state.totalSold}/5).`:`${state.totalSold} clients servis · Soignez le dosage pour gagner des pourboires.`;$('progress').style.setProperty('--progress',Math.min(100,state.totalSold*20)+'%');$('serviceStatus').textContent=state.closing?'DERNIÈRE TOURNÉE':state.open?'OUVERT':'FERMÉ';$('open').disabled=state.open||state.gameOver;$('open').textContent=state.open?'Service en cours':'Ouvrir le bar';$('end').disabled=!state.open||state.closing;
 $('customers').innerHTML=state.orders.length?state.orders.map(o=>`<div class="customer"><strong>${o.name}</strong> · ${recipes[o.recipe].name}<small>${money(recipes[o.recipe].price)} · ${Math.ceil(o.patience)} s de patience</small><div class="patience"><i style="width:${Math.max(0,o.patience)}%"></i></div><button data-serve="${o.id}" ${!state.tray.some(t=>t.recipe===o.recipe)?'disabled':''}>Servir la boisson</button></div>`).join(''):'<p class="empty">'+(state.open?'Un instant de calme. Préparez votre prochain service.':'Ouvrez à 17 h et accueillez vos premiers habitués.')+'</p>';
 $('stock').innerHTML=Object.entries(ingredients).map(([k,i])=>`<div class="row"><span>${i.name}</span><b>${Math.round(state.stock[k]*10)/10} ${i.unit}</b></div>`).join('')+state.deliveries.map(d=>`<p class="delivery">Livraison : ${ingredients[d.key].name} · ${Math.ceil(d.remaining)} s</p>`).join('');
 $('upgrade').disabled=state.upgraded||state.totalSold<5||state.cash<100||state.gameOver;$('upgrade').textContent=state.upgraded?'Installé':'Agrandir · 100 €';$('upgradeText').textContent=state.upgraded?'Plateau de 4 boissons installé.':'Un plateau de 4 boissons, après 5 clients servis.';$('trayCount').textContent=`PLATEAU ${state.tray.length}/${state.capacity}`;
 $('recipes').innerHTML=Object.entries(recipes).map(([id,r])=>`<button class="recipe ${state.prep?.recipe===id?'active':''}" data-recipe="${id}" ${!state.open||state.prep||!game.canMake(id)||state.tray.length>=state.capacity?'disabled':''}><b>${r.name}</b>${money(r.price)}<small>${r.station}</small></button>`).join('');
 const p=state.prep;let html='<p class="empty">Choisissez une boisson. Sélectionnez le récipient, puis réalisez les étapes de la recette. Les ingrédients sont prélevés dès le début.</p>';
 if(p){let r=recipes[p.recipe];html=`<div class="sectionTitle"><strong>${r.name}</strong><span>${r.glass}</span></div><p class="steps">${r.steps.map((s,i)=>i===p.step?'<strong>'+s+'</strong>':s).join(' → ')}</p>`;
 if(p.ready)html+=`<p>Dosage : <strong>${p.quality}%</strong> · ${p.quality<40?'La boisson sera refusée.':p.quality>=85?'Excellent ! Pourboire possible.':'Boisson acceptable.'}</p><div class="actions"><button class="primary" data-action="plate">Poser sur le plateau</button>`;
 else if(game.isPour())html+=`<p>Objectif : ${r.target} ${r.unit} · <span class="amount" id="amount"></span></p><div class="pourbar"><em></em><i id="fill"></i></div><div class="actions"><button class="primary" id="pour" data-action="pour">Maintenir pour ${p.recipe==='coffee'?'extraire':'verser'}</button><button data-action="finish">Valider le dosage</button>`;
 else html+=`<div class="actions"><button class="primary" data-action="step">${p.recipe==='mojito'&&p.step===5?'Mélanger et terminer':r.steps[p.step]}</button>`;
 html+='<button data-action="discard">Jeter</button></div>'}
 // Preserve the held button during pouring; replace only when the preparation stage changes.
 const viewKey=p?`${p.recipe}:${p.step}:${p.ready}`:'empty';if($('prep').dataset.view!==viewKey){$('prep').innerHTML=html;$('prep').dataset.view=viewKey}
 if(p&&game.isPour()){$('amount').textContent=p.amount.toFixed(1)+' '+recipes[p.recipe].unit;$('fill').style.width=Math.min(100,p.amount/(recipes[p.recipe].target*1.5)*100)+'%'}
 $('tray').innerHTML=state.tray.length?state.tray.map((t,i)=>`<span class="drink">${recipes[t.recipe].name} · ${t.quality}% <button data-remove="${i}" aria-label="Jeter cette boisson">×</button></span>`).join(''):'<span class="empty">Plateau vide · Les boissons restent ici jusqu’au service.</span>';
}
$('open').onclick=()=>act(()=>game.open());$('end').onclick=()=>act(()=>game.close());$('upgrade').onclick=()=>act(()=>game.upgrade());$('recipes').onclick=e=>{let b=e.target.closest('[data-recipe]');if(b)act(()=>game.start(b.dataset.recipe))};$('customers').onclick=e=>{let b=e.target.closest('[data-serve]');if(b)act(()=>game.serve(+b.dataset.serve))};$('tray').onclick=e=>{let b=e.target.closest('[data-remove]');if(b)act(()=>game.discard(+b.dataset.remove))};
$('prep').onclick=e=>{const b=e.target.closest('[data-action]');if(!b||b.dataset.action==='pour')return;act(()=>{switch(b.dataset.action){case 'step':if(game.s.prep.recipe==='mojito'&&game.s.prep.step===5)game.finishMix();else game.step();break;case 'finish':game.finishPour();break;case 'plate':return game.plate();case 'discard':return game.discard()}})};
$('prep').onpointerdown=e=>{let b=e.target.closest('#pour');if(b&&!paused){b.setPointerCapture(e.pointerId);game.setPour(true);e.preventDefault()}};$('prep').onpointerup=$('prep').onpointercancel=()=>game.setPour(false);
function supplier(){modal('Cave & fournisseur',`<p>Livraison en 10 secondes de jeu. Le jeu est en pause pendant la commande.</p>${Object.entries(ingredients).map(([k,i])=>`<div class="row"><span>${i.name}<br><small>${i.pack} ${i.unit} par lot</small></span><button data-buy="${k}">${money(i.cost)} · Commander</button></div>`).join('')}<p id="orderFeedback">Disponible : ${money(state.cash)}</p>`)}
$('order').onclick=supplier;$('modalContent').onclick=e=>{const b=e.target.closest('[data-buy]');if(b){if(paused){$('orderFeedback').textContent='Reprenez la partie avant de commander.';return}$('orderFeedback').textContent=game.buy(b.dataset.buy)+' Disponible : '+money(state.cash);save();ui()}if(e.target.id==='confirmReset'){game.s=new Game().s;state=game.s;paused=false;$('prep').dataset.view='';save();$('modal').close();ui();toast('Votre nouveau bar est prêt.')}};$('close').onclick=()=>$('modal').close();$('pause').onclick=()=>{paused=!paused;game.setPour(false);keys={};ui()};
$('help').onclick=()=>modal('Bienvenue derrière le bar',`<p>1. Ouvrez le bar. Les clients commandent au comptoir.</p><p>2. Choisissez leur boisson, puis le bon récipient. Pour un mojito, ajoutez et préparez les ingrédients dans l’ordre.</p><p>3. Maintenez le bouton pour doser. Relâchez à la quantité cible, puis validez. Un écart important provoque un refus.</p><p>4. Posez la boisson sur le plateau, puis cliquez sur « Servir » sous la commande du client.</p><p>Surveillez les stocks et commandez avant la rupture. Les livraisons arrivent après 10 secondes de jeu. Les boissons jetées consomment leurs ingrédients.</p><p>Le bar ferme à minuit. Vous pouvez demander la dernière tournée plus tôt. Les clients restants doivent être servis ou partir avant le bilan. Frais : 35 € par soir.</p><p>Commandes personnalisables dans Réglages · F11 : plein écran Windows. Cliquez sur le décor pour la souris, Échap pour la libérer et ouvrir les réglages. Le jeu se met en pause si vous changez de fenêtre.</p>`);
$('reset').onclick=()=>modal('Commencer un nouveau bar ?',`<p>Cette action remplace la sauvegarde actuelle. Vous repartez au premier soir avec 260 € et les ingrédients de départ.</p><button id="confirmReset">Confirmer le nouveau bar</button>`);
// Depth-tested 3D scene.
const canvas=$('world');let camera={x:6,y:1.65,z:7,a:Math.PI,pitch:0},keys={};let boxes=[];
function box(x,y,z,w,h,d,c,solid=true){boxes.push({x,y,z,w,h,d,c,solid})}
box(6,-.15,5,12,.3,10,'#b39872',false);box(6,3.25,5,12,.2,10,'#e4d7b8',false);box(0,1.5,5,.15,3,10,'#648575');box(12,1.5,5,.15,3,10,'#648575');box(6,1.5,0,12,3,.15,'#547868');box(6,1.5,10,12,3,.15,'#456b60');
// Back bar, bottles, tap handles, espresso machine and bistro tables.
for(let x=2;x<11;x+=2){box(x,1.5,.45,1.9,2.6,.65,'#3b3a2e');for(let y=.6;y<2.7;y+=.8){box(x,y,.85,1.95,.07,.9,'#ba9968');for(let j=0;j<6;j++){let c=['#4e7461','#b99555','#79423d'][j%3];box(x-.75+j*.3,y+.25,.85,.15,.45,.17,c,false);box(x-.75+j*.3,y+.51,.85,.08,.12,.09,'#d1b77a',false)}}}
box(6,.52,2.9,8,1.04,1.2,'#634631');box(6,1.1,2.9,8.2,.15,1.4,'#d4b27c');
box(4.1,1.35,2.9,1.1,.4,.7,'#babeb3');box(4.1,1.7,2.9,.12,.7,.12,'#c3c5b2');box(4.4,1.9,2.9,.5,.12,.12,'#c3c5b2');
box(8.4,1.5,2.8,1.2,.7,.7,'#384844');box(8.4,1.8,3.18,.85,.16,.09,'#c0b794');box(8.4,1.3,3.1,1.1,.08,.8,'#bbb6a5');
box(6.4,1.36,2.9,.6,.4,.4,'#394c42');
for(let z=5.7;z<9;z+=2.7){for(let x of [2.2,9.7]){box(x,.83,z,1.4,.12,1.3,'#a98555');box(x,.4,z,.15,.8,.15,'#373e31');for(let d of [-1,1]){box(x+d,.53,z,.55,.12,.55,'#684d37');box(x+d,.25,z,.12,.5,.12,'#3c4032')}}}
for(let x=3;x<11;x+=3){box(x,1.6,9.85,2.7,2.2,.03,'#587a76',false);box(x,2.8,9.7,2.8,.2,.1,'#c1a475',false);box(x,2.9,5,.06,.5,.06,'#3b3d31',false);box(x,2.65,5,.7,.12,.7,'#dcaf67',false)}
let renderer=null;
try{renderer=new BarRenderer(canvas,boxes)}catch(error){$('graphicsError').hidden=false;$('graphicsError').textContent=error.message;console.error(error)}
function render(){if(!renderer)return;const dynamic=[];
 if(state.upgraded)dynamic.push({x:10,y:.6,z:5,w:1.5,h:1.2,d:1,c:'#71563b'},{x:10,y:1.45,z:5,w:.7,h:.5,d:.5,c:'#c5bbaa'});
 for(const [i,customer]of state.orders.entries()){const x=4.6+i*1.4,z=4.3;dynamic.push({x,y:.85,z,w:.55,h:.9,d:.4,c:['#a96c49','#5c7c78','#8a6265'][i%3]},{x,y:1.55,z,w:.38,h:.4,d:.36,c:'#c99570'},{x:x-.17,y:.25,z,w:.2,h:.5,d:.25,c:'#394b49'},{x:x+.17,y:.25,z,w:.2,h:.5,d:.25,c:'#394b49'})}
 renderer.render(camera,dynamic,preferences);
}
function walk(dx,dz){let nx=camera.x+dx,nz=camera.z+dz;if(nx<.3||nx>11.7||nz<.4||nz>9.6)return;if(boxes.some(b=>b.solid&&b.y-b.h/2<1.7&&b.y+b.h/2>.2&&Math.abs(nx-b.x)<b.w/2+.2&&Math.abs(nz-b.z)<b.d/2+.2))return;camera.x=nx;camera.z=nz}
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(!paused&&!menusOpen()){movement(dt);const orderId=state.nextId;const report=game.tick(dt);if(state.nextId>orderId)audio.chime('arrival');if(report){save();modal('Bilan du soir '+report.day,`<p>${report.sold} clients servis · ${report.lost} clients perdus · ${report.waste} boissons jetées</p><p>Recettes et pourboires : ${money(report.revenue)}</p><p>Achats et améliorations : ${money(report.expenses)}</p><p>Charges : ${money(report.charges)}</p><h2>Résultat : ${money(report.profit)}</h2><p>${state.gameOver?'Trésorerie épuisée. Vous pouvez commencer un nouveau bar.':'Le prochain service commence à 17 h. Votre partie est sauvegardée.'}</p>`)}elapsed+=dt;if(elapsed>.12){ui();elapsed=0}}audio.setState(!paused&&!menusOpen()&&state.open,!!state.prep?.pouring);if(now-lastRender>=1000/preferences.fps-.5){render();lastRender=now}requestAnimationFrame(frame)}
ui();setInterval(save,5000);addEventListener('beforeunload',save);
